def count_Primes_nums(n):
    if n < 2:  # no prime numbers less than 2
        return 0

    sieve = [1] * n
    sieve[0] = 0  # 1 is not a prime number
    for i in range(1, int(n**0.5) + 1):
        if sieve[i]:  # if sieve[i] == 1
            for j in range(i*2, n, i+1):
                sieve[j] = 0  # mark multiples of prime numbers as non-prime
    return sum(sieve)

